const gsLocal=()=>{try{return JSON.parse(localStorage.getItem(GS_KEY)||'{}')}catch(_){return {}}};const gsSetLocal=o=>{try{localStorage.setItem(GS_KEY,JSON.stringify({...gsLocal(),...o}))}catch(_){}};
