function gsEstado(t){UI.gsEst=t;const e=$('#gs-st');if(e)e.textContent=t;const b=$('#gsBadge');if(b){b.title='Google: '+t;b.classList.toggle('err',/erro|conflito/.test(t));b.classList.toggle('run',/a sincronizar/.test(t))}}
