addEventListener('visibilitychange',()=>{try{const c=S.cfg.gsync;if(document.visibilityState==='hidden'&&c&&c.email&&_gsTok&&(S._ts||0)>(gsLocal().lts||0))sincronizarGoogle(false)}catch(_){}});
