/* importados: evitar duplicados quando o mesmo ficheiro é lido duas vezes ao mesmo tempo */
{const _gi2=guardarImportado;const voo=new Set();guardarImportado=async function(tipo,f){if(!f)return;const k=f.name+'|'+f.size;if(voo.has(k)){setTimeout(()=>{const x=importados().find(z=>z.nome===f.name&&z.tam===f.size);if(x&&!/importad|^Importação/.test(tipo)){x.tipo=tipo;save()}},1500);return}voo.add(k);try{return await _gi2.apply(this,arguments)}finally{setTimeout(()=>voo.delete(k),3000)}}}
/* sincronização: “houve alterações locais?” compara o conteúdo (não a hora da última gravação) */
function hashEstado(){let s;try{const {audit,_ts,...r}=S;const c={...r.cfg};delete c.gsync;delete c.avVistos;s=JSON.stringify({...r,cfg:c})}catch(_){return 0}let h=5381;for(let i=0;i<s.length;i++)h=((h<<5)+h+s.charCodeAt(i))|0;return h}
{const _env=gsEnviar;gsEnviar=async function(){const r=await _env.apply(this,arguments);gsSetLocal({lh:hashEstado()});return r}}
{const _rec=gsReceber;gsReceber=async function(){const r=await _rec.apply(this,arguments);gsSetLocal({lh:hashEstado()});return r}}
{const _sg=sincronizarGoogle;sincronizarGoogle=function(interativo,forcar){const L=gsLocal();if(!forcar&&L.lh!=null&&L.lh===hashEstado()){/* sem alterações reais: alinhar a hora local para não haver falsos conflitos */gsSetLocal({lts:S._ts||0})}return _sg.apply(this,arguments)}}
/* ---------- Definições › Professor ---------- */
const perfil=()=>S.cfg.perfil=S.cfg.perfil||{};
const CARGOS=['Diretor(a) de turma','Coordenador(a) de departamento','Delegado(a) de grupo','Coordenador(a) de diretores de turma','Coordenador(a) de projeto','Membro do Conselho Pedagógico','Membro da direção / Conselho Executivo','Professor(a) bibliotecário(a)','Coordenador(a) do jornal da escola','Equipa do jornal da escola','Tutor(a)','Avaliador(a) externo(a)'];
function fotoProf(sz){const p=perfil();sz=sz||40;const n=S.cfg.professor||'';const ini=n.split(/\s+/).filter(Boolean).map(w=>w[0]).filter((_,i,a)=>i===0||i===a.length-1).join('').toUpperCase()||'?';
  return p.foto?`<img class="pfoto" src="${p.foto}" alt="${esc(n)}" style="width:${sz}px;height:${sz}px">`:`<span class="pfoto vz" style="width:${sz}px;height:${sz}px;font-size:${Math.round(sz*.38)}px">${esc(ini)}</span>`}
const PF_ESC=['email','numero','atendimento','grupo','departamento','situacao','cargos'];
function perfilEsc(id){const p=perfil();id=id||escAtiva();p.porEscola=p.porEscola||{};let o=p.porEscola[id];
  if(!o){o=p.porEscola[id]={};if(id==='principal'){if(typeof S.cfg.email==='string'&&S.cfg.email)o.email=S.cfg.email;if(S.cfg.grupo)o.grupo=S.cfg.grupo;PF_ESC.forEach(k=>{if(p[k]!=null&&o[k]==null)o[k]=p[k]})}}return o}
const _strE=v=>typeof v==='string'?v.trim():'';
const emailProf=id=>{const pe=perfilEsc(id);if(pe&&pe.email&&typeof pe.email!=='string')pe.email='';return _strE(pe&&pe.email)||(((id||escAtiva())==='principal')?_strE(S.cfg.email):'')||''};
function defProf(){const c=S.cfg,p=perfil();const a=A();const ES=todasEscolas();const eid=UI.pfEsc&&ES.some(e=>escId(e)===UI.pfEsc)?UI.pfEsc:escAtiva();const e=escolaPorId(eid);const q=perfilEsc(eid);
  const DT=a?minhasDT(a).filter(n=>a.turmas.some(t=>escId(escolaDe(t))===eid&&turmasDaClasse(t).some(x=>normTurma(x)===normTurma(n)))):[];const disc=minhasDisc();
  const sel=ES.length>1?`<div class="pfesc"><span class="mut">Dados profissionais em</span><div class="seg">${ES.map(x=>`<button type="button" data-pfesc="${escId(x)}" class="${escId(x)===eid?'on':''}">${x.logo?`<img src="${x.logo}" alt="" style="width:18px;height:18px;object-fit:contain;border-radius:4px">`:ic('building',14)} ${esc(nomeEscola(x))}</button>`).join('')}</div></div>`:'';
  return `<div class="card ed"><div class="pfh"><div class="pfz" id="pf-drop">${fotoProf(112)}<button class="btn sm" id="pf-pick">${ic('image',14)} ${p.foto?'Alterar':'Adicionar'} Fotografia</button>${p.foto?`<button class="btn sm dng" id="pf-del">${ic('trash',14)} Remover</button>`:''}<input type="file" id="pf-f" accept="image/*" hidden></div>
    <div class="pfi2"><h2 style="margin:0">${esc(c.professor?profNome(c.professor):'O Seu Perfil')}</h2><div class="mut">${esc([q.grupo&&'Grupo '+q.grupo,q.departamento,nomeEscola(e)].filter(Boolean).join(' · '))}</div>${emailProf(eid)?`<div class="mut">${ic('chat',13)} ${esc(emailProf(eid))}</div>`:''}
      <div class="row" style="gap:6px;margin-top:8px;flex-wrap:wrap">${DT.map(n=>`<span class="tag dt">${ic('crown',12)} ${tituloDT(c.professor)} ${esc(n)}</span>`).join('')}${(q.cargos||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></div></div>
   <h3>Dados Pessoais <span class="mut" style="font-weight:500;text-transform:none;letter-spacing:0">· iguais em todas as escolas</span></h3><div class="g2">
    <div><label>Nome completo</label><input data-pf="professor" data-raiz="1" value="${esc(c.professor||'')}"></div>
    <div><label>Nome nos documentos</label><input value="${esc(profNome(c.professor||''))}" disabled title="Gerado a partir do nome completo: Prof. + primeiro + último nome"></div>
    <div><label>Género</label><select data-pf="genero" title="Usado em “Diretor/Diretora” e “Professor/Professora”">${(()=>{const g=p.genero||(c.professor?guessGen(c.professor):'')||'M';return `<option value="F" ${g==='F'?'selected':''}>Feminino</option><option value="M" ${g!=='F'?'selected':''}>Masculino</option>`})()}</select></div>
    <div><label>E-mail pessoal</label><input data-pf="emailPessoal" type="email" inputmode="email" value="${esc(p.emailPessoal||'')}"></div>
    <div><label>Telemóvel</label><input data-pf="telefone" inputmode="tel" value="${esc(p.telefone||'')}"></div>
    <div><label>Anos de serviço</label><input data-pf="anosServico" type="number" min="0" value="${esc(p.anosServico||'')}"></div></div>
   <div class="pfbox"><div class="row" style="gap:10px;flex-wrap:wrap"><h3 style="margin:0">${e.logo?`<img src="${e.logo}" alt="" style="width:22px;height:22px;object-fit:contain;vertical-align:-5px;border-radius:5px;margin-right:6px">`:ic('building',16)+' '}${esc(nomeEscola(e))}</h3><span class="sp1"></span>${sel}</div>
   <p class="hint" style="margin:4px 0 8px">Estes dados mudam consoante a escola (o e-mail institucional, o número, o grupo, o departamento e os cargos de cada escola). Ao mudar de escola na barra de cima, a app usa os dessa escola.</p><div class="g2">
    <div><label>E-mail institucional</label><input data-pfe="email" type="email" inputmode="email" value="${esc(emailProf(eid))}" placeholder="nome@${esc(((e.emailEscola||'').split('@')[1])||'edu.azores.gov.pt')}"></div>
    <div><label>N.º de docente / funcionário</label><input data-pfe="numero" value="${esc(q.numero||'')}"></div>
    <div><label>Horário de atendimento aos EE</label><input data-pfe="atendimento" value="${esc(q.atendimento||'')}" placeholder="ex.: 3.ª feira, 10h20–11h05, sala 2.08"></div>
    <div><label>Grupo de recrutamento</label><input data-pfe="grupo" value="${esc(q.grupo||'')}" placeholder="ex.: 330 — Inglês"></div>
    <div><label>Departamento</label><input data-pfe="departamento" value="${esc(q.departamento||'')}" placeholder="ex.: Línguas"></div>
    <div><label>Situação</label><select data-pfe="situacao">${['','Quadro de escola','Quadro de zona pedagógica','Contratado(a)','Destacado(a)','Outra'].map(x=>`<option ${q.situacao===x?'selected':''}>${x}</option>`).join('')}</select></div></div>
   <label style="margin-top:10px">Disciplinas que leciona nesta escola</label><p style="margin:2px 0 0">${(()=>{const D=[...new Set((a?a.turmas:[]).filter(t=>escId(escolaDe(t))===eid).map(t=>t.disciplina))];return (D.length?D:disc).map(d=>`<span class="tag">${esc(d)}</span>`).join(' ')||'<span class="mut">Sem turmas nesta escola.</span>'})()}</p>
   <h3>Cargos e Funções nesta Escola</h3><div class="pfcg">${CARGOS.map(x=>`<label class="chk"><input type="checkbox" data-pfc="${esc(x)}" ${(q.cargos||[]).includes(x)?'checked':''}> ${esc(x)}</label>`).join('')}</div></div>
   <h3>Assinatura Digitalizada</h3><div class="row" style="gap:8px">${c.assinaturaImg?`<img src="${c.assinaturaImg}" alt="Assinatura" style="height:52px;background:#fff;border:1px solid var(--line);border-radius:8px;padding:4px">`:'<span class="mut">Sem assinatura.</span>'}<button class="btn sm" id="pf-ass">${ic('upload',14)} ${c.assinaturaImg?'Substituir':'Carregar'}</button>${c.assinaturaImg?`<button class="btn sm dng" id="pf-assx">${ic('trash',14)}</button>`:''}<input type="file" id="pf-af" accept="image/*" hidden></div>
   <p class="hint">Usada nos PDF (relatórios, planos, documentos gerados). A fotografia aparece na barra lateral. Tudo fica só neste dispositivo, na cópia de segurança e na sincronização Google (se ligada).</p>
   <label style="margin-top:10px">Notas</label><textarea data-pf="notas" rows="3" placeholder="Formação, projetos, observações…">${esc(p.notas||'')}</textarea></div>`}
function bindProf(){const p=perfil();const ES=todasEscolas();const eid=UI.pfEsc&&ES.some(e=>escId(e)===UI.pfEsc)?UI.pfEsc:escAtiva();const q=perfilEsc(eid);
  $$('[data-pf]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.pf;if(el.dataset.raiz)S.cfg[k]=el.value.trim();else p[k]=el.value.trim();save();audit('Professor','Perfil alterado',k);if(k==='professor'||k==='genero')setTimeout(()=>{vDefinicoes();sessBox()},0)}));
  $$('[data-pfe]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.pfe;q[k]=el.value.trim();if(eid==='principal'&&(k==='email'||k==='grupo'))S.cfg[k]=q[k];save();audit('Professor','Perfil alterado',k+' · '+nomeEscola(escolaPorId(eid)));if(k==='grupo'||k==='departamento'||k==='email')setTimeout(vDefinicoes,0)}));
  $$('[data-pfesc]').forEach(b=>b.onclick=()=>{UI.pfEsc=b.dataset.pfesc;vDefinicoes()});
  $$('[data-pfc]').forEach(c=>c.onchange=()=>{const antes=jnOn();q.cargos=$$('[data-pfc]').filter(x=>x.checked).map(x=>x.dataset.pfc);if(/jornal/i.test(c.dataset.pfc)){S.cfg.modulos=S.cfg.modulos||{};delete S.cfg.modulos.jornal}save();try{jnNav();jnBadge();const dep=jnOn();if(dep!==antes){audit('Jornal',dep?'Módulo ativado pelo cargo':'Módulo ocultado (sem cargo)',c.dataset.pfc);toast(dep?'Módulo Jornal Escolar ativado — está na barra lateral':'Módulo Jornal Escolar ocultado (os dados ficam guardados)',dep?'ok':'')}}catch(_){}setTimeout(vDefinicoes,0)});
  const pick=()=>$('#pf-f').click();$('#pf-pick').onclick=pick;const z=$('#pf-drop .pfoto');if(z)z.onclick=pick;
  const usar=f=>fotoDeFicheiro(f).then(u=>{p.foto=u;save();audit('Professor','Fotografia','');vDefinicoes();sessBox()}).catch(e=>alert(e.message));
  $('#pf-f').onchange=e=>{const f=e.target.files[0];if(f)usar(f)};const dz=$('#pf-drop');dz.ondragover=e=>{e.preventDefault();dz.classList.add('over')};dz.ondragleave=()=>dz.classList.remove('over');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('over');const f=e.dataTransfer.files[0];if(f&&/image/.test(f.type))usar(f)};
  const dl=$('#pf-del');if(dl)dl.onclick=()=>{if(confirm('Remover a fotografia?')){delete p.foto;save();vDefinicoes();sessBox()}};
  $('#pf-ass').onclick=()=>$('#pf-af').click();$('#pf-af').onchange=async e=>{const f=e.target.files[0];if(!f)return;S.cfg.assinaturaImg=await logoDeFicheiro(f);save();vDefinicoes()};const ax=$('#pf-assx');if(ax)ax.onclick=()=>{delete S.cfg.assinaturaImg;save();vDefinicoes()}}
