{const _vd=varsDoc;varsDoc=function(ctx){const V=_vd.apply(this,arguments);try{const a=A();const t=ctx&&ctx.turma?a.turmas.find(z=>z.id===ctx.turma):T();const eid=t?escId(escolaDe(t)):escAtiva();const q=perfilEsc(eid);Object.assign(V,{email_professor:emailProf(eid),grupo_professor:q.grupo||'',departamento:q.departamento||'',atendimento_ee:q.atendimento||'',telefone_professor:(perfil().telefone||'')})}catch(_){}return V}}
