function testarPopups(){const ag=Date.now();const ex=[{k:'teste:1',ic:'alert',cor:'#c0392b',t:'Aviso de teste: entregar as pautas',s:'Exemplo de aviso programado · '+new Date().toLocaleString('pt-PT',{dateStyle:'short',timeStyle:'short'})},
    {k:'teste:2',ic:'meet',cor:'#0f8b8d',t:'Conselho de Turma (exemplo)',s:'Começa daqui a 25 min · Sala de reuniões',ir:()=>go('reunioes')},{k:'teste:3',ic:'checks',cor:'#e07a00',t:'Corrigir os testes (exemplo)',s:'Tarefa em atraso (há 2 dias)',ir:()=>go('tarefas')},
    {k:'teste:4',ic:'file',cor:'#7a4fd0',t:'Enviar a matriz do Teste 2 (exemplo)',s:'Teste na próxima semana',ir:()=>go('testes')}];
  const orig=avisosUrgentes;const vistos=JSON.stringify(S.cfg.avVistos||{});avisosUrgentes=()=>ex.filter(x=>!(S.cfg.avVistos||{})[x.k]);$('#avpop')&&$('#avpop').remove();mostrarAvisos(true);avisosUrgentes=orig;
  const obs=new MutationObserver(()=>{if(!document.getElementById('avpop')){obs.disconnect();try{S.cfg.avVistos=JSON.parse(vistos);save()}catch(_){}}});obs.observe(document.body,{childList:true});audit('Ferramentas','Teste dos pop-ups','')}
function cartaoTestePopups(){const N='Notification' in window?Notification.permission:'';
  return `<div class="card avpc"><h2 style="margin:0 0 4px">${ic('bell',18)} Avisos em Pop-up</h2><p class="hint" style="margin:0 0 14px">Veja como aparecem os avisos de testes, prazos, reuniões e tarefas.</p>
  <div class="avpg"><div class="avpt"><span class="avpi">${ic('alert',20)}</span><div><b>Avisos reais</b><span>O que está agora por tratar nas suas turmas.</span></div><button class="btn pri" id="ft-popr">${ic('eye',15)} Ver Avisos</button></div>
  <div class="avpt"><span class="avpi t">${ic('sparkle',20)}</span><div><b>Exemplo</b><span>Mostra avisos de exemplo. Não altera nada.</span></div><button class="btn" id="ft-pop">${ic('bell',15)} Testar Pop-up</button></div></div>
  <div class="avpn ${N==='granted'?'ok':''}">${N==='granted'?`${ic('check',15)} Notificações do sistema autorizadas — recebe avisos mesmo com a app em segundo plano.`:N?`${ic('bell',15)} <span>Receba avisos mesmo com a app em segundo plano.</span> <a href="#" id="ft-notif">Autorizar notificações do sistema</a>`:`${ic('info',15)} Este navegador não permite notificações do sistema.`}</div></div>`}
{const _df=defFerramentas;defFerramentas=function(){return cartaoTestePopups()+_df.apply(this,arguments)};const _bf=bindFerramentas;bindFerramentas=function(){_bf.apply(this,arguments);$('#ft-pop').onclick=testarPopups;$('#ft-popr').onclick=()=>mostrarAvisos(true);const n=$('#ft-notif');if(n)n.onclick=e=>{e.preventDefault();Notification.requestPermission().then(r=>{toast(r==='granted'?'Notificações autorizadas':'Notificações não autorizadas',r==='granted'?'ok':'aviso');vDefinicoes()})}}}
/* notificação do sistema quando a app está em segundo plano */
{const _ma=mostrarAvisos;mostrarAvisos=function(forcar){const r=_ma.apply(this,arguments);try{if(document.visibilityState==='hidden'&&'Notification' in window&&Notification.permission==='granted'){const L=avisosUrgentes();const k=L.map(x=>x.k).join('|');if(L.length&&k!==mostrarAvisos._ult){mostrarAvisos._ult=k;window.__ntNotif('EduSpruce — '+L.length+' aviso'+(L.length>1?'s':'')+' urgente'+(L.length>1?'s':''),{body:L.slice(0,3).map(x=>x.t).join('\n'),tag:'eduflow-avisos'})}}}catch(_){}return r}}
